def classifier_env(source: Mapping[str, str]) -> dict[str, str]:
    """Build the (secret-stripped) env for the classifier subprocess."""
    env = {key: value for key, value in source.items() if key in _ENV_ALLOWLIST}
    path = _EXTRA_PATH + ":" + env.get("PATH", "")
    home = source.get("HOME")
    if home:
        path = path + ":" + os.path.join(home, ".local", "bin")
    env["PATH"] = path
    env["BUBO_ROOT"] = str(ROOT)
    return env

def classify_developer_reply(cfg: ReviewConfig, finding_text: str, reply_text: str) -> JsonObject:
    """Classify a developer reply as accept/reject via the configured agent.

    Returns ``{"verdict": "accepted"|"rejected"|"unclear", "false_positive":
    bool}``. Degrades to ``unclear`` on any failure so it never raises into
    the outcome-sync loop.
    """
    if not reply_text.strip():
        return _unclear()
    command = list(cfg.reviewer_command)
    if not command:
        return _unclear()
    prompt = build_prompt(finding_text, reply_text)
    try:
        result = run_bounded(
            [*command, prompt],
            env=classifier_env(os.environ),
            timeout=CLASSIFY_TIMEOUT_SECONDS,
        )
    except Exception as exc:  # spawn / timeout / OS error — retry later
        log("reply_classify_failed", error=type(exc).__name__)
        return _error()
    if result.returncode:
        log("reply_classify_nonzero", returncode=result.returncode)
        return _error()
    return parse_verdict(result.stdout or "")

def classifier_env(
    source: Mapping[str, str], cfg: ReviewConfig | None = None
) -> dict[str, str]:
    """Build the env for the classifier subprocess.

    Credentials remain stripped by default. As with the main reviewer, a
    configured OpenAI-compatible endpoint needs exactly ``LLM_API_KEY`` and
    ``LLM_BASE_URL`` at request time, so forward only those two values when
    the operator explicitly configured ``llm_base_url``.
    """
    env = {key: value for key, value in source.items() if key in _ENV_ALLOWLIST}
    path = _EXTRA_PATH + ":" + env.get("PATH", "")
    home = source.get("HOME")
    if home:
        path = path + ":" + os.path.join(home, ".local", "bin")
    env["PATH"] = path
    env["BUBO_ROOT"] = str(ROOT)
    if cfg is not None and cfg.llm_base_url:
        for name in ("LLM_API_KEY", "LLM_BASE_URL"):
            if source.get(name):
                env[name] = source[name]
    return env

def classify_developer_reply(cfg: ReviewConfig, finding_text: str, reply_text: str) -> JsonObject:
    """Classify a developer reply as accept/reject via the configured agent.

    Returns ``{"verdict": "accepted"|"rejected"|"unclear", "false_positive":
    bool}``. Degrades to ``unclear`` on any failure so it never raises into
    the outcome-sync loop.
    """
    if not reply_text.strip():
        return _unclear()
    command = list(cfg.reviewer_command)
    if not command:
        return _unclear()
    prompt = build_prompt(finding_text, reply_text)
    try:
        result = run_bounded(
            [*command, prompt],
            env=classifier_env(os.environ, cfg),
            timeout=CLASSIFY_TIMEOUT_SECONDS,
        )
    except Exception as exc:  # spawn / timeout / OS error — retry later
        log("reply_classify_failed", error=type(exc).__name__)
        return _error()
    if result.returncode:
        log("reply_classify_nonzero", returncode=result.returncode)
        return _error()
    return parse_verdict(result.stdout or "")

def build_data() -> JsonObject:
    """Assemble the full ``data.json`` document — read-only, never mutating.

    Guards on ``paths.DB.exists()`` first: a missing DB returns the empty
    skeleton without opening any connection (so the export never creates the
    operator's database). When the DB exists but is empty the readers return
    empty aggregates and the same shape is produced. ``ConfigError`` and a
    partially-migrated DB degrade gracefully rather than crash.
    """
    version = _installed_version()
    if not paths.DB.exists():
        return _empty_skeleton(version)

    cfg = _load_config()
    try:
        reviews = _recent_reviews()
        reports = _reports()
        health = _health(cfg.timeout_seconds)
        inflight = db.count_inflight_workers()
    except (sqlite3.OperationalError, FileNotFoundError):
        # DB exists but is not a usable bubo DB (truncated / pre-schema).
        return _empty_skeleton(version)

    return {
        "meta": {
            "generated_at": now(),
            "schema_version": SCHEMA_VERSION,
            "db_present": True,
        },
        "version": {"installed": version, "update": None},
        "health": health,
        "inflight": inflight,
        # The dashboard is a curated slice the SPA can render without scanning
        # the full lists: the most recent reviews + the report windows.
        "dashboard": {
            "recent": reviews[:10],
            "reports": reports,
        },
        "reviews": reviews,
        "reports": reports,
        "config": _config_schema(cfg),
    }

type User = { tenantId: string };
type Doc = { tenantId: string; text: string };
declare const db: { getDocument(id: string): Promise<Doc | undefined> };
async function readDoc(user: User, id: string, requestedTenant: string): Promise<Doc> {
  if (user.tenantId !== requestedTenant) throw new Error('forbidden');
  const doc = await db.getDocument(id);
  if (!doc) throw new Error('not found');
  return doc;
}

type User = { tenantId: string };
type Doc = { tenantId: string; text: string };
declare const db: { getDocument(id: string): Promise<Doc | undefined> };
async function readDoc(user: User, id: string, requestedTenant: string): Promise<Doc> {
  if (user.tenantId !== requestedTenant) throw new Error('forbidden');
  const doc = await db.getDocument(id);
  if (!doc) throw new Error('not found');
  if (doc.tenantId !== user.tenantId) throw new Error('forbidden');
  return doc;
}

package counts
import "sync"
func Count(keys []string) map[string]int {
 counts := map[string]int{}
 var wg sync.WaitGroup
 for _, key := range keys {
  wg.Add(1)
  go func(k string) { defer wg.Done(); counts[k]++ }(key)
 }
 wg.Wait()
 return counts
}

package counts
import "sync"
func Count(keys []string) map[string]int {
 counts := map[string]int{}
 var wg sync.WaitGroup
 var mu sync.Mutex
 for _, key := range keys {
  wg.Add(1)
  go func(k string) { defer wg.Done(); mu.Lock(); counts[k]++; mu.Unlock() }(key)
 }
 wg.Wait()
 return counts
}

#include <stddef.h>
#include <string.h>
int copy_text(char *dst, size_t cap, const char *src, size_t len) {
 if (len > cap) return -1;
 memcpy(dst, src, len);
 dst[len] = '\0';
 return 0;
}

